import { update, save } from "@/api/treeManager/pzsx";
export default {
  name: "pzsxAddEdit",
  props: ['fromValue', 'isShow', 'type'],
  data: function data() {
    return {
      submitParams: {},
      rules: {
        value: [{
          required: true,
          message: '',
          trigger: 'blur',
          validator: function validator(rule, value, callback) {
            if (value) {
              // 1 开头的默认是手机号，进行校验
              var reg = /^[0-9]*$/;
              if (reg.test(value) === false) {
                callback(new Error('属性ID只允许输入数字'));
              } else {
                callback();
              }
            } else {
              callback('请输入属性ID');
            }
          }
        }],
        name: [{
          required: true,
          message: '属性英文名不能为空',
          trigger: 'blur'
        }],
        type: [{
          required: true,
          message: '属性类型不能为空',
          trigger: 'blur'
        }],
        remark: [{
          required: true,
          message: '属性描述不能为空',
          trigger: 'blur'
        }]
      },
      saveLoading: false
    };
  },
  computed: {
    typeList: function typeList() {
      return [{
        name: '属性',
        id: 0
      }, {
        name: '配置',
        id: 1
      }, {
        name: '模型',
        id: 2
      }, {
        name: '字典模型',
        id: 3
      }];
    }
  },
  mounted: function mounted() {
    if (this.type == 'edit') {
      this.submitParams = JSON.parse(JSON.stringify(this.fromValue));
    }
  },
  methods: {
    submit: function submit() {
      var _this = this;
      this.$refs.submitForm.validate(function (valid) {
        if (valid) {
          if (_this.type == 'add') {
            _this.saveLoading = true;
            save(_this.submitParams).then(function (res) {
              _this.saveLoading = false;
              _this.$message.success('添加成功');
              _this.$emit("close");
              _this.$emit("refreshData");
            });
          } else if (_this.type == 'edit') {
            _this.saveLoading = true;
            update(_this.submitParams).then(function (res) {
              _this.saveLoading = false;
              _this.$message.success('修改成功');
              _this.$emit("close");
              _this.$emit("refreshData");
            });
          }
        }
      });
    },
    getTitle: function getTitle(type) {
      if (type == 'add') {
        return '新 增';
      } else if (type == 'edit') {
        return '更 新';
      }
      return null;
    }
  }
};
